const categoryTheme={nutri:{color:'#ffa340',icon:'◈',label:'Nutrition'},eco:{color:'#55c8dc',icon:'◎',label:'Environnement'},nova:{color:'#ba92ff',icon:'▥',label:'Transformation'},compare:{color:'#ed6aa4',icon:'⇄',label:'Comparaison'}};
function categoryBadge(){const c=categoryTheme[room?.mode||'nutri'];return `<div class="category-badge"><span aria-hidden="true">${c.icon}</span><div><b>${currentMode().name}</b></div></div>`;}
const currentMode=()=>modes[room?.mode||'nutri'];
let clockNoticeKey='';
let lobbyView=false,lastRevision=-1,lastGame='',wheelStep=-1,wheelStepKey='';
const fmt=n=>Math.round(n).toLocaleString('fr-CA'),uuid=()=>crypto.randomUUID().replaceAll('-','');
let token,profile={name:'',avatar:'🦊'},room=null,roomId=new URL(location.href).searchParams.get('room'),lastRoom='',viewKey='',rosterKey='',phaseKey='',offset=0,pollTimer,pollBusy=false,busy=false,selected='🦊',toastTimer,sound=window.NutriAudio.enabled,lastBeat=-1,pendingChoice=null,voteBusy=false,createOperation=uuid(),lastResponse=0;
try{token=localStorage.getItem('nutrideck.multiplayer.token');if(!/^[a-f0-9]{64}$/.test(token||'')){token=uuid()+uuid();localStorage.setItem('nutrideck.multiplayer.token',token);}profile=JSON.parse(localStorage.getItem('nutrideck.multiplayer.profile')||'null')||profile;lastRoom=localStorage.getItem('nutrideck.multiplayer.lastRoom')||'';selected=avatars.includes(profile.avatar)?profile.avatar:'🦊';}catch{app.innerHTML='<div class="error-box"><h1>Active le stockage du navigateur</h1><p>Il permet de retrouver ton joueur après avoir quitté pour Messenger.</p></div>';return;}
const mine=()=>room?.players.find(p=>p.id===room.me),isHost=()=>room?.host===room?.me,now=()=>Date.now()+offset;
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function online(ok){$('#connection').hidden=ok;$('#connection').textContent='Reconnexion… Ta place et tes points sont conservés.';}
async function api(path,data){const r=await fetch('/api/rooms'+path,{method:data===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),cache:'no-store',signal:AbortSignal.timeout(path.endsWith('/start')?100000:15000)});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Connexion impossible.'),{status:r.status});online(true);return d;}
function accept(d){if(roomId===d.id&&(d.revision<lastRevision||(d.revision===lastRevision&&d.serverNow<lastResponse)))return;lastRevision=d.revision;lastResponse=d.serverNow;offset=d.serverNow-Date.now();if(lastGame&&d.gameId!==lastGame)lobbyView=false;lastGame=d.gameId;const previous=room;room=d;if(previous&&previous.id===d.id){if(previous.phase!==d.phase){const event={loading:'start',wheel:'wheel',vote:'tap',reveal:'lock',standings:'ranking'}[d.phase];if(event)cue(event);}if(d.players.length>previous.players.length)sfx('join');if(d.players.some(p=>p.id!==d.me&&p.voted&&!previous.players.find(x=>x.id===p.id)?.voted))sfx('vote');if(d.players.some(p=>p.id!==d.me&&p.ready&&!previous.players.find(x=>x.id===p.id)?.ready))sfx('ready');}document.body.dataset.category=d.mode||'nutri';document.body.style.setProperty('--category',categoryTheme[d.mode||'nutri'].color);if(d.me){roomId=d.id;localStorage.setItem('nutrideck.multiplayer.lastRoom',roomId);if(new URL(location.href).searchParams.get('room')!==roomId)history.replaceState(null,'','/?room='+roomId);}render();updateVoteJuice();}
function phase(){if(!room)return'entry';if(room.roulette){if(room.phase==='standings')return'ranking';if(room.phase==='results'||room.phase==='reveal'&&now()>=room.landAt)return now()<room.landAt+1000?'spinning':'answer';}if(room.phase==='reveal'){if(now()-room.lockAt<900)return'votes';if(!room.landed)return'spinning';return now()<room.landAt+1500?'answer':'ranking';}if(room.phase==='results')return'ranking';return room.phase;}
function showFinal(){return room?.phase==='finished'||(room?.phase==='lobby'&&room.lastFinal?.players.some(p=>p.id===room.me)&&!lobbyView);}
function picker(){return `<div class="avatar-grid" role="group" aria-label="Ton avatar">${avatars.map(a=>`<button type="button" data-avatar="${a}" aria-label="Avatar ${a}" aria-pressed="${selected===a}">${a}</button>`).join('')}</div>`;}
function readWeights(){const inputs=[...document.querySelectorAll('[data-weight]')];return inputs.length?Object.fromEntries(inputs.map(el=>[el.dataset.weight,Number(el.value)])):{...NutriRules.defaults};}
function weightControls(){const w=room?.categoryWeights||NutriRules.defaults;return `<details class="weight-settings"><summary>Catégories <span>100 %</span></summary><div class="weight-preview" aria-hidden="true">${NutriRules.keys.map(k=>`<i data-weight-segment="${k}" style="flex-basis:${w[k]}%;background:${categoryTheme[k].color}"></i>`).join('')}</div>${NutriRules.keys.map(k=>`<label class="weight-row" style="--slider-color:${categoryTheme[k].color}"><span>${modes[k].name}</span><output data-weight-value="${k}">${w[k]} %</output><input type="range" min="0" max="100" step="1" value="${w[k]}" data-weight="${k}" aria-label="Pourcentage ${modes[k].name}" aria-valuetext="${w[k]} pour cent"></label>`).join('')}<button type="button" class="secondary-button weight-reset">Réinitialiser</button></details>`;}
function applyWeights(w){document.querySelectorAll('[data-weight]').forEach(el=>{const k=el.dataset.weight;el.value=w[k];el.setAttribute('aria-valuetext',w[k]+' pour cent');document.querySelector(`[data-weight-value="${k}"]`).textContent=w[k]+' %';document.querySelector(`[data-weight-segment="${k}"]`).style.flexBasis=w[k]+'%';});}
app.addEventListener('input',e=>{const key=e.target.dataset.weight;if(!key)return;const weights=Object.fromEntries([...document.querySelectorAll('[data-weight-value]')].map(el=>[el.dataset.weightValue,parseInt(el.textContent,10)]));applyWeights(NutriRules.rebalance(weights,key,e.target.value));});
app.addEventListener('click',e=>{if(e.target.closest('.weight-reset'))applyWeights(NutriRules.defaults);});
function controls(){return `<div class="settings-grid"><label class="full-field">Produits vendus dans<select id="country">${Object.entries(countries).map(([k,v])=>`<option value="${k}" ${(room?.country||'canada')===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Questions<input id="count" type="number" min="1" max="30" step="1" value="${room?.questionCount||7}" inputmode="numeric" required></label></div><details class="advanced-settings"><summary>Durées et bouton prêt</summary><div class="settings-grid"><label>Vote · secondes<input id="seconds" type="number" min="1" max="3600" step="1" value="${room?.seconds||20}" inputmode="numeric" required></label><label>Délai après réponse · secondes<input id="ready-seconds" type="number" min="1" max="3600" step="1" value="${room?.readySeconds||10}" inputmode="numeric" required></label><label class="ready-setting"><input id="ready-enabled" type="checkbox" ${room?.readyEnabled!==false?'checked':''}> Bouton « Je suis prêt »</label></div></details>${weightControls()}`;}
function readOptions(){return{roulette:true,questionCount:Number($('#count').value),count:Number($('#count').value),seconds:Number($('#seconds').value),readySeconds:Number($('#ready-seconds').value),readyEnabled:$('#ready-enabled').checked,country:$('#country').value,categoryWeights:readWeights()};}
function entry(){const joining=!!roomId;app.innerHTML=`<section class="entry"><span class="eyebrow">${joining?'INVITATION':'1 À 8 JOUEURS'}</span><h1>${joining?'Rejoindre la partie':'Nouvelle partie'}</h1>${!joining&&/^[a-f0-9]{32}$/.test(lastRoom)?`<a class="resume-link" href="/?room=${lastRoom}">Reprendre ma partie</a>`:''}${!joining?'<details class="join-link"><summary>J’ai un lien d’invitation</summary><form id="join-link-form"><label>Lien reçu<input name="invite" type="text" placeholder="Colle le lien ici" required></label><button class="primary-button" type="submit">Rejoindre</button></form></details>':''}<form id="entry-form" class="setup-panel"><label>Ton nom<input id="name" maxlength="24" placeholder="Ton nom" autocomplete="nickname" value="${esc(profile.name)}" required></label><details class="avatar-picker"><summary><span id="selected-avatar">${selected}</span> Choisir mon avatar</summary>${picker()}</details>${joining?`<p class="join-count">${room?room.players.length+' / 8 joueurs':'Connexion…'}</p>`:controls()}<button class="primary-button" type="submit" ${joining&&(!room||room.phase!=='lobby')?'disabled':''}>${joining?'Entrer dans le salon':'Créer la partie'}</button>${joining&&room&&room.phase!=='lobby'?'<p class="lobby-error">Partie en cours. Tu pourras entrer au prochain salon.</p>':''}</form>${joining?'<details class="recovery-entry"><summary>Reprendre ma place</summary><form id="recover-form"><label>Mon code personnel<input name="code" autocomplete="off" autocapitalize="none" placeholder="Code depuis Table → Ma place" required></label><button class="primary-button">Récupérer ma place</button></form></details><a href="/" class="link-home">Créer une partie</a>':''}</section>`;if(joining&&/FBAN|FBAV|Messenger|Instagram/i.test(navigator.userAgent))app.querySelector('.entry h1').insertAdjacentHTML('afterend','<p class="messenger-hint">Ouvre ce lien dans Safari ou Chrome avant de rejoindre. Dans Messenger : menu ⋯ → Ouvrir dans le navigateur.</p>');}

function lobby(){app.innerHTML=`<section class="lobby"><div class="room-topline"><span class="eyebrow">SALON</span><span class="room-code">${room.players.length} / 8</span></div><h1>À vous de jouer.</h1><div class="lobby-summary">${esc(countries[room.country])} · ${room.questionCount||room.total} questions</div><div class="share-row"><button class="primary-button" data-action="share">Inviter</button><button class="secondary-button" data-action="copy">Copier le lien</button></div><div class="lobby-layout"><div class="table-side"><aside class="players-panel"><div class="panel-heading"><h2>Les joueurs</h2><span id="ready-count"></span></div><div id="players"></div></aside><div id="lobby-actions" class="lobby-actions"></div><p id="lobby-error" class="lobby-error" hidden></p></div><form id="profile-form" class="setup-panel lobby-options"><details><summary>${mine().avatar} ${esc(mine().name)} · Modifier mon profil</summary><label>Ton nom<input id="name" maxlength="24" autocomplete="nickname" value="${esc(mine().name)}" required></label>${picker()}<button id="profile-save" class="secondary-button" type="submit">Enregistrer</button></details>${isHost()?`<details class="room-settings"><summary>Réglages de la partie</summary>${controls()}<button class="secondary-button" type="button" data-action="settings">Appliquer</button></details>`:'<p class="guest-settings" id="guest-settings"></p>'}</form></div></section>`;rosterKey='';}

function topBar(){let controls=$('#game-top-controls');if(!controls){controls=document.createElement('div');controls.id='game-top-controls';document.querySelector('.app-header').append(controls);controls.addEventListener('click',e=>{const a=e.target.closest('[data-top]')?.dataset.top;if(a==='sound'){sound=window.NutriAudio.toggle();tone();topBar();}if(a==='copy')share(true);if(a==='table')manageTable();});}const active=room?.me&&!['lobby','loading','finished'].includes(room.phase);controls.hidden=false;controls.innerHTML=`<span class="top-round">${active?room.round+' / '+room.total:''}</span><button data-top="sound" aria-label="${sound?'Couper':'Activer'} le son" aria-pressed="${sound}">${sound?'Son on':'Son off'}</button><button data-top="table" ${room?.me?'':'hidden'}>Table</button><button data-top="copy" ${room?.me?'':'hidden'} aria-label="Copier le lien du salon">Lien</button>`;}
function playerStrip(){const ready=room?.phase==='results'||room?.phase==='intro',ranked=[...(room?.players||[])].sort((a,b)=>b.score-a.score),top=ranked[0]?.score||0;const html=ranked.map(p=>{const done=ready?p.ready:p.voted,state=done?(ready?'Prêt':'A voté'):'En attente',crown=top>0&&p.score===top;return `<span class="strip-player ${done?'done':''} ${p.id===room.me?'is-me':''}" title="${esc(p.name)} · ${fmt(p.score)} points · ${state}" aria-label="${esc(p.name)}, ${fmt(p.score)} points, dernière question +${p.award}, ${state}"><span class="strip-avatar">${p.avatar}</span>${crown?'<i class="strip-crown" aria-label="En tête">♛</i>':''}<small aria-hidden="true">${done?'✓':'◷'}</small>${room.landed?`<b class="strip-award">+${fmt(p.award)}</b>`:''}</span>`;}).join('');document.querySelectorAll('.players-strip').forEach(el=>{if(el.innerHTML!==html)el.innerHTML=html;});}
function gameShell(){app.innerHTML=`<div class="players-strip" aria-label="État des joueurs"></div><ol class="timeline"><li data-phase="vote">01 · Vote</li><li data-phase="answer">02 · Réponse</li><li data-phase="points">03 · Points</li><li data-phase="final">04 · Classement</li></ol><div id="winner"></div><div class="arena-layout"><section class="main-stage"><div id="stage"><div id="game-heading"></div><div id="wheel-area"></div><div id="insights"></div><div class="vote-product" id="vote-product"></div><div id="ballot"></div></div><div id="action-dock" class="action-dock"></div></section><aside class="players-panel"><div class="panel-heading"><h2>Autour de la table</h2><span id="ready-count"></span></div><div id="players"></div><details class="rules"><summary>Comment on marque des points</summary><p>${room.mode==='compare'?'Bon produit : 100 points. Autre produit : 0.':`Réponse exacte : ${room.scoreUnit||100} points. Un cran d’écart : ${(room.scoreUnit||100)*.6}. Deux crans : ${(room.scoreUnit||100)*.25}. Au-delà : 0.`}</p><p>${room.scoreVersion>=2?'Jusqu’à 20 points de vitesse en plus pour une réponse exacte. Le dernier changement compte. ' :''}Ton choix reste modifiable jusqu’au dernier vote ou à la fin du temps.</p></details></aside></div><footer class="gym-footer"><span>NutriDeck</span><a href="https://world.openfoodfacts.org" target="_blank" rel="noopener">Données ODbL · photos CC BY-SA · Open Food Facts</a></footer>`;phaseKey='';rosterKey='';}
function mountCard(){if(room.mode==='compare'){mountComparison();return;}const container=$('#vote-product');if(!container||!room.product)return;const key=room.product.code+':'+room.landed;if(container.dataset.key===key)return;const old=container.querySelector('.nd-card'),face=old?.dataset.face||'front';window.NutriDeckCards.dispose(old);const card=window.NutriDeckCards.create(room.product,{masked:!room.landed});card.setFace(face,false);container.replaceChildren(card);container.dataset.key=key;}
const metricKey=k=>({proteins:'prot'}[k]||k);
let inspection=null,inspectionCard=null;
function closeInspection(){if(inspection){window.NutriDeckCards.dispose(inspectionCard);inspection.close();inspection.remove();inspection=null;inspectionCard=null;}}
function mountComparison(){const box=$('#vote-product'),c=room.comparison;if(!box||!c)return;const key=c.products.map(p=>p.code).join(':')+':'+room.landed;if(box.dataset.key===key)return;box.querySelectorAll('.nd-card').forEach(window.NutriDeckCards.dispose);box.replaceChildren();box.classList.add('comparison-cards');c.products.forEach((p,i)=>{const wrap=document.createElement('div');wrap.className='comparison-mini';const button=document.createElement('div');button.setAttribute('role','button');button.tabIndex=0;button.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspectProduct(i);}};button.dataset.inspect=i;button.className='inspect-mini';button.setAttribute('aria-label','Inspecter '+(p.product_name_fr||p.product_name));const card=window.NutriDeckCards.create(p,{maskedMetric:room.landed?null:metricKey(c.metric)});card.inert=true;button.append(card);wrap.innerHTML=`<b class="comparison-letter">${['A','B'][i]}</b>`;wrap.append(button);const hint=document.createElement('span');hint.className='inspect-hint';hint.textContent='Agrandir';wrap.append(hint);box.append(wrap);});box.dataset.key=key;}
function inspectProduct(index){if(room.phase!=='vote'||!room.comparison)return;closeInspection();const c=room.comparison,p=c.products[index],choice=['A','B'][index];inspection=document.createElement('dialog');inspection.className='inspection-dialog';inspection.innerHTML=`<header><b>${choice} · ${esc(c.label)} masqué</b><button class="inspection-close" aria-label="Fermer">✕</button></header><div class="inspection-body"></div><footer><button class="secondary-button inspection-flip">Retourner</button><button class="primary-button inspection-vote">Choisir ${choice}</button></footer>`;inspectionCard=window.NutriDeckCards.create(p,{maskedMetric:metricKey(c.metric)});inspection.querySelector('.inspection-body').append(inspectionCard);inspection.querySelector('.inspection-close').onclick=closeInspection;inspection.querySelector('.inspection-flip').onclick=()=>inspectionCard.setFace(inspectionCard.dataset.face==='front'?'back':'front',true);inspection.querySelector('.inspection-vote').onclick=()=>{closeInspection();vote(choice);};inspection.addEventListener('cancel',e=>{e.preventDefault();closeInspection();});document.body.append(inspection);inspection.showModal();}
function manageTable(){if(!room?.me)return;const dialog=document.createElement('dialog');dialog.className='table-dialog';const code=room.recoveryCode?.match(/.{1,4}/g)?.join('-')||'';dialog.innerHTML=`<header><h2>La table</h2><button data-close aria-label="Fermer">✕</button></header><section><h3>Ma place</h3><p>Pour revenir depuis un autre navigateur : ouvre le lien du salon, puis « Reprendre ma place ».</p><code>${esc(code)}</code><button class="secondary-button" data-code>Copier mon code</button><small>Garde ce code pour toi. Il change après récupération.</small></section>${isHost()?`<section><h3>Les joueurs</h3>${room.players.map(p=>`<div class="manage-player"><span>${p.avatar} ${esc(p.name)}</span>${p.id!==room.me?`<button data-remove="${p.id}" class="secondary-button">Retirer</button>`:'<small>Toi · hôte</small>'}</div>`).join('')}<div class="remove-confirm" hidden></div></section>`:''}`;document.body.append(dialog);dialog.showModal();const close=()=>{dialog.close();dialog.remove();};dialog.querySelector('[data-close]').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.querySelector('[data-code]').onclick=async()=>{try{await navigator.clipboard.writeText(code);dialog.querySelector('[data-code]').textContent='Copié ✓';}catch{dialog.querySelector('code').setAttribute('tabindex','0');const range=document.createRange();range.selectNodeContents(dialog.querySelector('code'));getSelection().removeAllRanges();getSelection().addRange(range);}};dialog.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{const p=room.players.find(p=>p.id===button.dataset.remove);if(!p)return;const confirm=dialog.querySelector('.remove-confirm');confirm.hidden=false;confirm.innerHTML=`<p>Retirer ${esc(p.name)} de cette partie ?</p><button class="secondary-button" data-cancel>Annuler</button><button class="primary-button" data-confirm>Retirer</button>`;confirm.querySelector('[data-cancel]').onclick=()=>confirm.hidden=true;confirm.querySelector('[data-confirm]').onclick=async()=>{if(await command('remove',{playerId:p.id})){close();toast(p.name+' a été retiré.');}};});}
function stagePhase(){const p=phase(),cfg=currentMode();if(p!=='vote')closeInspection();document.body.dataset.playPhase=p;if(p===phaseKey){mountCard();updateInsights();return;}phaseKey=p;const voting=p==='vote',rank=p==='ranking',answer=p==='answer'||rank;if(room.roulette&&answer){$('.arena-layout').classList.toggle('standings-show',rank);$('#action-dock').hidden=true;mountCard();updateResultShow();if(rank){document.querySelectorAll('.timeline li').forEach(el=>el.classList.toggle('active',el.dataset.phase==='final'));}if(rank)requestAnimationFrame(()=>$('.players-panel')?.scrollIntoView({block:'start',behavior:'smooth'}));return;}$('.arena-layout').classList.toggle('reveal-mode',!voting);$('.arena-layout').classList.toggle('answer-summary',answer);const active=voting?'vote':rank?'final':answer?'points':'answer';document.querySelectorAll('.timeline li').forEach(el=>el.classList.toggle('active',el.dataset.phase===active));
$('#game-heading').innerHTML=voting?`${categoryBadge()}${room.mode==='compare'?`<h1 class="compare-question">Lequel contient le plus de ${esc(room.comparison?.label.toLowerCase())} ?</h1>`:''}<details class="score-explainer"><summary>${room.mode==='compare'?'Comment jouer':'Comprendre la note'}</summary>${introDescription(room.mode)}</details>`:`<p class="question-kicker">${p==='votes'?'VOTES VERROUILLÉS':answer?'LA RÉPONSE ÉTAIT':'ET LA RÉPONSE ÉTAIT…'}</p><h1 class="reveal-caption">${p==='votes'?'':answer?room.skipped?'Produit passé · aucun point':'':''}</h1>`;
$('#wheel-area').innerHTML=voting?'':`<div class="answer-wheel ${answer?'landed-answer':''}" id="wheel"><span class="wheel-pointer"></span><b id="wheel-value">${answer?esc(room.revealTarget):p==='votes'?'••':cfg.values[0]}</b></div><div class="mini-grade-line">${cfg.values.map(g=>`<b data-wheel-grade="${g}">${g}</b>`).join('')}</div>`;
$('#ballot').innerHTML=voting?`<div class="ballot"><div class="grade-options" style="grid-template-columns:repeat(${cfg.values.length},1fr)" role="group" aria-label="Choisir ${cfg.name}">${cfg.values.map((g,i)=>`<button class="grade-option" data-grade="${g}" style="--grade:${cfg.colors[i]}" aria-pressed="false">${room.mode==='compare'?'Choisir '+g:g}</button>`).join('')}</div></div>`:'';
$('#action-dock').innerHTML=voting?`<div class="vote-clock" id="vote-clock"><div class="clock-number"><b id="clock-number"></b><span id="clock-label"></span></div><div class="clock-meta"><strong id="vote-status"></strong><span id="vote-hint"></span></div><div class="clock-track"><i></i></div></div>${isHost()?'<button class="skip-product" data-action="skip">Photo inutilisable ? Passer le produit</button>':''}`:'<p class="dock-hint">'+(room.phase==='results'?'Prêt pour la suite ? Le bouton est au bas de l’écran.':'Les points et les repères du produit se dévoilent.')+'</p>';
if(p==='votes'||p==='answer'&&!room.roulette)requestAnimationFrame(()=>$('.arena-layout').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));
$('#announcement').textContent=voting?'Nouvelle manche. '+cfg.question:p==='answer'?'La réponse était '+room.revealTarget:'Votes verrouillés.';if(p==='answer'&&!room.roulette)cue('answer');mountCard();updateInsights();}
function updateInsights(){if(room.roulette){updateResultShow();return;}const container=$('#insights');if(!container)return;if(!room.landed||!room.insights){container.innerHTML='';return;}const key=room.gameId+':'+room.round;if(container.dataset.key!==key){container.dataset.key=key;container.innerHTML=`<section class="product-insights"><h2>${esc(room.insights.title)}</h2><ol>${room.insights.points.map((p,i)=>`<li data-insight="${i}" class="${p.tone}" hidden><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(p.label)}</h3><p>${esc(p.text)}</p></div></li>`).join('')}</ol><p class="insight-note">${esc(room.insights.note)} <a href="${room.insights.url}" target="_blank" rel="noopener">Fiche OFF</a></p></section>`;}
container.querySelectorAll('[data-insight]').forEach(el=>{el.hidden=now()<room.landAt+450+Number(el.dataset.insight)*850;});}
function roster(){playerStrip();if(!$('#players'))return;const p=phase(),lobbyState=['lobby','loading'].includes(room.phase),rank=['ranking','finished'].includes(p),show=!['vote','lobby','loading'].includes(p),land=['answer','ranking','finished'].includes(p);const key=JSON.stringify([room.players,rank,show,land,lobbyState]);if(key===rosterKey)return;rosterKey=key;const before=new Map([...document.querySelectorAll('.player-row')].map(el=>[el.dataset.player,el.getBoundingClientRect()]));const list=[...room.players].sort((a,b)=>(rank?b.score-a.score:b.base-a.base));
$('#players').innerHTML=list.map((x,i)=>`<div class="player-row ${x.id===room.me?'is-me':''} ${land&&x.vote===room.revealTarget&&!room.skipped?'correct-player':''}" data-player="${x.id}"><b class="sidebar-rank">${i+1}</b><span class="avatar">${x.avatar}</span><div class="player-info"><strong>${esc(x.name)}${land&&x.vote===room.revealTarget&&!room.skipped?'<span class="correct-check">✓</span>':''}</strong><small>${room.phase==='results'&&x.ready?'Prêt ✓':lobbyState?x.host?'Hôte':'À table':land?x.vote===null?'Sans vote':x.vote===room.revealTarget&&!room.skipped?'EXACT !':'Réponse : '+esc(room.revealTarget):x.voted?'A voté ✓':'Réfléchit…'}</small></div><span class="vote-chip ${show?'revealed':'unrevealed'}">${show?esc(x.vote||'—'):'—'}</span><div class="player-points"><b data-total="${x.id}">${fmt(rank?x.score:x.base)}</b><span class="awarded ${land?'':'pending-award'}">+${fmt(x.award)}</span></div></div>`).join('');
$('#ready-count').textContent=lobbyState?room.players.length+' / 8':rank?'TOTAL':room.players.filter(p=>p.voted).length+' / '+room.players.length;const title=$('.panel-heading h2');if(title)title.textContent=rank?'Classement':'Autour de la table';if(rank&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('.player-row').forEach(el=>{const a=before.get(el.dataset.player);if(a){const b=el.getBoundingClientRect();el.animate([{transform:`translateY(${a.top-b.top}px)`},{transform:'translateY(0)'}],{duration:600,easing:'cubic-bezier(.2,.8,.2,1)'});}});}
function clearResultShow(){const overlay=$('#result-show');if(overlay){$('#ready-dock')?.remove();overlay.remove();}app.inert=false;document.body.classList.remove('result-open');}
function tableFacts(){const players=[...room.players].sort((a,b)=>b.score-a.score),top=players[0],me=mine(),facts=[];if(top?.score>0){const leaders=players.filter(p=>p.score===top.score);facts.push(leaders.length>1?`${leaders.map(p=>p.name).join(' et ')} · à égalité en tête`:`${top.avatar} ${top.name} mène · ${fmt(top.score)} points`);if(me&&me.score<top.score)facts.push(`${fmt(top.score-me.score)} points te séparent de la tête`);}const streak=[...players].sort((a,b)=>(b.stats?.bestStreak||0)-(a.stats?.bestStreak||0))[0];if(streak?.stats?.bestStreak>1)facts.push(`${streak.avatar} ${streak.name} · série de ${streak.stats.bestStreak} bonnes réponses`);facts.push(`${room.total-room.round+1} question${room.total-room.round>0?'s':''} à jouer`);facts.push(room.scoreVersion>=2?'Réponse exacte · 100 points + jusqu’à 20 de vitesse':'Réponse exacte · +100 points');return facts;}
function rouletteScreen(){const colors={nutri:'#ffa340',eco:'#55c8dc',nova:'#ba92ff',compare:'#ed6aa4'},name={nutri:'Nutri-Score',eco:'Éco-Score',nova:'NOVA',compare:'Ça ou ça'};let sectors='';for(let i=0;i<100;i++){const a=i*3.6*Math.PI/180,b=(i+1)*3.6*Math.PI/180,slot=(i*37)%100,m=NutriRules.slotMode(slot,room.wheelWeights||(room.rouletteVersion>=2?NutriRules.defaults:{nutri:85,eco:10,nova:5,compare:0}));sectors+=`<path data-sector="${i}" d="M160 160 L${160+145*Math.sin(a)} ${160-145*Math.cos(a)} A145 145 0 0 1 ${160+145*Math.sin(b)} ${160-145*Math.cos(b)} Z" fill="${colors[m]}" stroke="#3b2518" stroke-width=".8"/>`;}
app.innerHTML=`<section class="roulette-scene" aria-label="Tirage de la catégorie"><div class="show-eyebrow">QUESTION ${room.round} / ${room.total}</div><h1>Prochaine catégorie</h1><div class="wheel-camera"><div class="roulette-entry"><div class="roulette-wrap"><div class="roulette-lights" aria-hidden="true">${Array.from({length:20},(_,i)=>`<i style="--bulb:${i}"></i>`).join('')}</div><div class="roulette-pointer" aria-hidden="true"></div><svg class="category-wheel" viewBox="0 0 320 320" aria-hidden="true">${sectors}</svg><div class="wheel-hub"><span>LE GRAND</span><b>TIRAGE</b><small>100 cases</small></div></div></div></div><div class="wheel-ticker" aria-live="off"></div><div class="category-pop" hidden><div class="category-mark" aria-hidden="true">${categoryTheme[room.mode].icon}</div><h2>${name[room.mode]}</h2><div>${introDescription(room.mode)}</div>${room.requestedTotal>room.total?`<small>${room.total} questions disponibles sur ${room.requestedTotal}.</small>`:''}<div class="category-progress"><i></i></div></div></section>`;window.scrollTo({top:0,behavior:'instant'});document.querySelector('.app-header').inert=false;}
let rouletteTick=-1,rouletteFrame;
function tickRoulette(){cancelAnimationFrame(rouletteFrame);const scene=$('.roulette-scene');if(!scene)return;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches,t=Math.max(0,Math.min(1,(now()-room.wheelAt)/(room.wheelEndAt-room.wheelAt))),angle=2160-((room.wheelSlot*73)%100+.5)*3.6,ease=1-(1-t)**4;$('.category-wheel').style.transform=`rotate(${reduced?angle:angle*ease}deg)`;const step=Math.floor(angle*ease/3.6);scene.style.setProperty('--wheel-speed',t>.8?'1':'.3');const ticker=$('.wheel-ticker'),messages=tableFacts(),message=messages[Math.floor((now()-room.wheelAt)/2300)%messages.length];if(ticker&&ticker.textContent!==message){ticker.textContent=message;ticker.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:300});}if(step!==rouletteTick&&t<1){rouletteTick=step;sfx('wheelTick');}const landed=t>=1,pop=now()>=room.wheelEndAt+850;if(landed)cue('wheelStop','wheel-land');if(pop)cue('category_'+room.mode,'category-pop');scene.classList.toggle('category-landed',landed);scene.classList.toggle('category-explained',pop);$('.roulette-wrap').style.setProperty('--wheel-zoom',reduced?1:.72+1.83*(t*t*(3-2*t)));$('.roulette-wrap').style.setProperty('--wheel-pan',reduced?'0px':`${$('.roulette-wrap').offsetWidth*.5*Math.max(0,(t-.48)/.52)*2.1}px`);scene.querySelector(`[data-sector="${(room.wheelSlot*73)%100}"]`)?.classList.toggle('winning-sector',landed);$('.category-pop').hidden=!pop;scene.style.setProperty('--intro-progress',Math.max(0,Math.min(1,(now()-room.wheelEndAt-850)/(room.introEndAt-room.wheelEndAt-850))));rouletteFrame=requestAnimationFrame(tickRoulette);}
function stickerCopy(p){let text=p.text.replace(/ pour 100 g \/ 100 ml/g,' / 100 g ou ml').replace(/\. NOVA décrit le degré et le but de la transformation\./,'').replace(/ dans le calcul OFF/g,'');if(text.length>155)text=text.slice(0,152).replace(/\s+\S*$/,'')+'…';return text;}
function updateResultShow(){if(!room.roulette)return;if(phase()!=='answer'){clearResultShow();return;}let overlay=$('#result-show');if(!overlay){const origin=$('#wheel')?.getBoundingClientRect();overlay=document.createElement('section');overlay.id='result-show';overlay.className='result-show';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','La réponse et les points');document.body.append(overlay);overlay.innerHTML=`<button class="result-table" type="button">Table</button><div class="result-stage"><div class="players-strip" aria-label="Joueurs prêts"></div><div class="result-heading">${categoryBadge()}<span class="show-eyebrow">LA RÉPONSE ÉTAIT</span><div class="result-grade" style="--answer-color:${currentMode().colors[currentMode().values.indexOf(room.revealTarget)]}">${esc(room.revealTarget)}</div><div class="result-personal"><div class="your-answer"><span>Ta réponse</span><b id="show-choice">${esc(mine()?.vote||'—')}</b></div><span id="show-points">+0</span><small id="speed-bonus" hidden></small></div></div><div class="sticker-board" aria-live="polite"></div><a class="result-source" target="_blank" rel="noopener">Source : Open Food Facts</a></div>`;overlay.querySelector('.result-table').onclick=manageTable;document.body.classList.add('result-open');app.inert=true;$('#show-points').setAttribute('aria-label','Points gagnés');const grade=overlay.querySelector('.result-grade'),dest=grade.getBoundingClientRect();if(origin&&origin.bottom>0&&origin.top<innerHeight&&!matchMedia('(prefers-reduced-motion:reduce)').matches)grade.animate([{transform:`translate(${origin.x+origin.width/2-dest.x-dest.width/2}px,${origin.y+origin.height/2-dest.y-dest.height/2}px) scale(${origin.width/dest.width},${origin.height/dest.height}) rotate(0deg)`},{transform:'translate(0,0) scale(1) rotate(-5deg)'}],{duration:380,easing:'cubic-bezier(.2,.8,.2,1)'});}
const points=room.mode==='compare'?[]:room.insights?.points||[],board=$('.sticker-board'),key=room.gameId+':'+room.round+':'+points.length;if(board.dataset.key!==key){board.dataset.key=key;board.dataset.count=Math.min(4,points.length);board.innerHTML=points.slice(0,4).map((p,i)=>`<article class="fact-sticker ${p.tone}" data-sticker="${i}" style="--i:${i};--angle:${[-1.5,1.5,-1,1][i]}deg" hidden><span class="sticker-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false">${p.tone==='good'?'<path d="M12 18V6m-5 5 5-5 5 5"/>':p.tone==='warm'?'<path d="M12 5v9"/><circle cx="12" cy="18" r="1.3" fill="currentColor" stroke="none"/>':'<circle cx="12" cy="12" r="4" fill="currentColor" stroke="none"/>'}</svg></span><div><h3>${esc(p.label)}</h3><p>${esc(stickerCopy(p))}</p></div></article>`).join('');}
if(room.mode==='compare'&&room.comparison?.values&&!overlay.querySelector('.compare-result')){const c=room.comparison;overlay.querySelector('.result-personal').insertAdjacentHTML('afterend',`<div class="compare-result">${c.products.map((p,i)=>`<div class="${room.revealTarget===['A','B'][i]?'is-winner':''}"><img src="${esc(p.image_front_url)}" alt=""><b>${['A','B'][i]} · ${esc(p.product_name_fr||p.product_name)}</b><strong>${Number(c.values[i]).toLocaleString('fr-CA',{maximumFractionDigits:2})} g</strong><small>/ 100 ${c.basis}</small></div>`).join('')}</div>`);overlay.classList.add('compare-reveal');}playerStrip();const elapsed=now()-room.landAt;document.querySelectorAll('[data-sticker]').forEach(el=>{const due=1600+Number(el.dataset.sticker)*750;el.hidden=elapsed<due;if(!el.hidden&&elapsed<due+400)cue(el.classList.contains('good')?'stickerGood':el.classList.contains('warm')?'stickerBad':'stickerInfo','sticker-'+el.dataset.sticker);});const source=$('.result-source');source.href=room.insights?.url||'https://world.openfoodfacts.org';source.title=room.insights?.note||'';const award=mine()?.award||0;if(award&&elapsed<2300)cue('points');const bonus=mine()?.speedBonus||0;$('#speed-bonus').hidden=!bonus||elapsed<1850;$('#speed-bonus').textContent='⚡ +'+bonus+' vitesse';if(bonus&&elapsed>=1850&&elapsed<2700)cue('speed');$('#show-choice').textContent=mine()?.vote||'—';$('#show-points').textContent='+'+fmt(award*(1-(1-Math.max(0,Math.min(1,(elapsed-1000)/850)))**3));}
function introDescription(m){if(m==='compare')return '<div class="category-guide"><h3>Lequel en contient le plus ?</h3><p>Deux produits, une valeur cachée. Inspecte les cartes, puis choisis.</p><div class="guide-factors"><span>Sel</span><span>Sucres</span><span>Gras</span><span>Fibres</span><span>Protéines</span></div></div>';if(m==='nova')return '<div class="category-guide"><h3>Degré de transformation</h3><div class="guide-scale nova-scale"><b>1<small>Peu transformé</small></b><b>2<small>Ingrédient culinaire</small></b><b>3<small>Transformé</small></b><b>4<small>Ultra-transformé</small></b></div><p class="guide-foot">Certains additifs révèlent l’ultra-transformation, pas leur dangerosité.</p></div>';if(m==='eco')return '<div class="category-guide"><h3>Impact environnemental</h3><div class="guide-endpoints"><b>A <span>Plus faible</span></b><b>E <span>Plus élevé</span></b></div><div class="guide-factors"><span>Production</span><span>Transport</span><span>Emballage</span></div><p class="guide-foot">L’empreinte du produit, de sa fabrication à ses déchets.</p></div>';return '<div class="category-guide"><h3>Qualité nutritionnelle</h3><div class="guide-endpoints"><b>A <span>Plus favorable</span></b><b>E <span>Moins favorable</span></b></div><div class="guide-balance"><div class="guide-minus"><b>Ça pèse contre</b><span>Calories · sucres<br>Sel · gras saturés</span></div><div class="guide-plus"><b>Ça aide</b><span>Fibres · protéines<br>Fruits · légumes</span></div></div><p class="guide-foot"><strong>Et les additifs ?</strong> Leur risque n’est pas évalué par cette note.</p></div>';}

function introScreen(){const cfg=currentMode();app.innerHTML=`<section class="phase-overlay" role="dialog" aria-modal="true" aria-labelledby="intro-title"><div class="intro-panel"><span class="eyebrow">${room.mode==='nutri'?'C’EST PARTI':'PHASE BONUS'}</span><div class="intro-number">${room.mode==='nutri'?'01':room.mode==='nova'?'02':room.novaCount?'03':'02'}</div><h1 id="intro-title">${cfg.name}</h1><span class="intro-count">${room.phaseTotal} produit${room.phaseTotal>1?'s':''} · ${esc(countries[room.country])}</span><div class="intro-copy">${introDescription(room.mode)}</div>${room.mode==='nutri'&&room.requestedTotal>room.total?`<p class="intro-note">${room.total} produit${room.total>1?'s':''} disponible${room.total>1?'s':''} sur ${room.requestedTotal} demandés.</p>`:''}<div class="intro-players">${room.players.map(p=>`<span title="${esc(p.name)}">${p.avatar}</span>`).join('')}</div><p class="intro-note">Tout le monde est prêt ? On y va.</p></div></section>`;}
function readyDock(show){let dock=$('#ready-dock');if(!show){dock?.remove();document.body.classList.remove('has-ready-dock');return;}document.body.classList.add('has-ready-dock');if(!dock){dock=document.createElement('div');dock.id='ready-dock';dock.className='ready-dock';dock.innerHTML='<div class="ready-meta"><strong id="gate-title"></strong><span id="gate-count"></span></div><div class="gate-clock"><b id="gate-time"></b><span>secondes</span></div><button class="primary-button" id="ready-button" aria-pressed="false">Prêt</button><div class="gate-track"><i></i></div>';dock.querySelector('button').onclick=()=>command('ready',{ready:!mine()?.ready});document.body.append(dock);}if(room.roulette&&$('#result-show'))$('#result-show').append(dock);tickReady();}
function tickReady(){playerStrip();const dock=$('#ready-dock');if(!dock)return;const standings=room.phase==='standings',deadline=standings?room.standingsEndAt:room.readyDeadline,automatic=standings||room.readyEnabled===false,seconds=Math.max(0,Math.ceil((deadline-now())/1000)),ready=room.players.filter(p=>p.ready).length,button=$('#ready-button');$('#gate-title').textContent=standings?room.round>=room.total?'Le palmarès arrive':'Prochaine roue':automatic?'La suite arrive…':room.phase==='intro'?'À vous de jouer':room.roulette?'On continue ?':'Prêt pour la suite ?';$('#gate-count').textContent=standings?'':automatic?'Passage automatique':`${ready} / ${room.players.length} prêts`;$('#gate-time').textContent=seconds;button.hidden=automatic;dock.classList.toggle('auto-only',automatic);button.textContent=mine()?.ready?'Prêt ✓':'Je suis prêt';button.setAttribute('aria-pressed',!!mine()?.ready);button.disabled=seconds===0||busy;dock.classList.toggle('gate-urgent',!standings&&seconds<=5);dock.style.setProperty('--remaining',Math.max(0,Math.min(1,(deadline-now())/(standings?2600:room.readySeconds*1000))));}
function trophyData(players){const awards=[],f=room.lastFinal||{},played=(f.history||[]).filter(h=>!h.skipped).length;
function top(key,title,icon,description,min=1){const best=Math.max(0,...players.map(p=>p.stats?.[key]||0));if(best<min)return;awards.push({title,icon,names:players.filter(p=>p.stats?.[key]===best).map(p=>p.name),value:description(best),detail:''});}
top('bestStreak','Ça chauffe !','🔥',n=>`${n} bonnes réponses de suite`,2);top('exact','Dans le mille','🎯',n=>`${n} bonne${n>1?'s':''} réponse${n>1?'s':''}`);top('near','À un cheveu','🤏',n=>`${n} réponse${n>1?'s':''} à un seul cran`);top('comebacks','Le retour !','🪃',n=>`${n} bonne${n>1?'s':''} réponse${n>1?'s':''} après une erreur`);top('optimist','Lunettes roses','🌈',n=>`${n} produit${n>1?'s':''} vu${n>1?'s':''} trop favorablement`);top('pessimist','Pas dupe… ou presque','🧐',n=>`${n} produit${n>1?'s':''} jugé${n>1?'s':''} trop sévèrement`);top('ecoExact','Radar écolo','🌿',n=>`${n} Éco-Score${n>1?'s':''} trouvé${n>1?'s':''}`);top('novaExact','Scanner NOVA','🔎',n=>`${n} groupe${n>1?'s':''} NOVA trouvé${n>1?'s':''}`);top('greenExact','Chasseur de A','🥬',n=>`${n} note${n>1?'s':''} A reconnue${n>1?'s':''}`);top('answered','Toujours dans le jeu','🎲',n=>`${n} réponse${n>1?'s':''} donnée${n>1?'s':''}`);
const perfect=played?players.filter(p=>p.stats?.exact===played):[];if(perfect.length)awards.push({title:'Sans faute !',icon:'👑',names:perfect.map(p=>p.name),value:`${played} sur ${played}. Rien n’est passé.`,detail:''});
const worst=Math.max(0,...players.map(p=>p.stats?.worst?.ratio||0)),w=worst?players.filter(p=>p.stats?.worst?.ratio===worst):[];if(w.length)awards.push({title:'Dans une autre galaxie',icon:'🛸',names:w.map(p=>p.name),value:'Le plus grand écart de la partie',detail:w.map(p=>{const v=p.stats.worst;return `${p.name} : ${v.guess} au lieu de ${v.answer} · ${v.product}`;}).join(' / ')});
const seed=f.gameId||room.gameId;const hash=title=>{let n=2166136261;for(const c of seed+title)n=Math.imul(n^c.charCodeAt(0),16777619);return n>>>0;};return awards.filter(a=>a.names.length<=2).sort((a,b)=>hash(a.title)-hash(b.title)).slice(0,4);}
function trophies(players){const awards=trophyData(players);if(!awards.length)return '';return `<section class="trophy-section trophy-carousel" aria-label="Les petits exploits"><div class="trophy-heading"><h2>Les petits exploits</h2><span id="trophy-count">1 / ${awards.length}</span></div><div class="trophy-grid" id="trophy-track" tabindex="0" aria-label="Faire défiler les exploits">${awards.map((a,i)=>`<article class="trophy" aria-label="${i+1} sur ${awards.length}"><span class="trophy-icon">${a.icon}</span><h3>${a.title}</h3><strong>${a.names.map(esc).join(' & ')}</strong><p>${esc(a.value)}</p>${a.detail?`<details><summary>Voir le détour</summary><p>${esc(a.detail)}</p></details>`:''}</article>`).join('')}</div><div class="trophy-controls"><button type="button" data-trophy="prev" aria-label="Exploit précédent">←</button><div class="trophy-dots">${awards.map((_,i)=>`<button type="button" data-trophy-index="${i}" aria-label="Exploit ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</div><button type="button" data-trophy="next" aria-label="Exploit suivant">→</button><button type="button" data-trophy="pause" class="trophy-play">Pause</button></div></section>`;}
let trophyTimer,trophyPaused=false,trophyIndex=0;
function stopTrophies(){clearInterval(trophyTimer);trophyTimer=null;}
function initTrophies(){stopTrophies();const track=$('#trophy-track'),section=$('.trophy-carousel');if(!track)return;const cards=[...track.children],reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;trophyIndex=0;trophyPaused=reduced;const pause=()=>{section.querySelector('[data-trophy=pause]').textContent=trophyPaused?'Défiler':'Pause';};const go=i=>{trophyIndex=(i+cards.length)%cards.length;track.scrollTo({left:cards[trophyIndex].offsetLeft-cards[0].offsetLeft,behavior:reduced?'instant':'smooth'});};pause();track.addEventListener('scroll',()=>{let nearest=0;cards.forEach((c,i)=>{if(Math.abs(c.offsetLeft-cards[0].offsetLeft-track.scrollLeft)<Math.abs(cards[nearest].offsetLeft-cards[0].offsetLeft-track.scrollLeft))nearest=i;});trophyIndex=nearest;$('#trophy-count').textContent=`${nearest+1} / ${cards.length}`;section.querySelectorAll('[data-trophy-index]').forEach((b,i)=>b.setAttribute('aria-pressed',i===nearest));},{passive:true});track.addEventListener('pointerdown',()=>{trophyPaused=true;pause();});section.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.trophy==='pause'){trophyPaused=!trophyPaused;pause();return;}sfx('tap');trophyPaused=true;pause();if(button.dataset.trophy==='prev')go(trophyIndex-1);else if(button.dataset.trophy==='next')go(trophyIndex+1);else if(button.dataset.trophyIndex!=null)go(Number(button.dataset.trophyIndex));});trophyTimer=setInterval(()=>{const rect=section.getBoundingClientRect();if(!trophyPaused&&!document.hidden&&!section.contains(document.activeElement)&&rect.top<innerHeight&&rect.bottom>0&&!section.querySelector('details[open]'))go(trophyIndex+1);},4500);}
function finalScreen(){const f=room.lastFinal,list=[...f.players].sort((a,b)=>b.score-a.score),rank=p=>1+list.filter(x=>x.score>p.score).length,top=list.filter(p=>rank(p)<=3),winners=list.filter(p=>rank(p)===1);app.innerHTML=`<section class="final-board"><div class="final-top"><span class="eyebrow">LA TABLE A PARLÉ</span><span class="room-code">${f.total} produits · ${esc(countries[f.country]||'Tous les pays')}</span></div><h1>Le palmarès.</h1><p class="final-lead">${winners.map(p=>esc(p.name)).join(' & ')} ${winners.length>1?'se partagent la victoire.':'remporte la partie.'}</p><div class="podium">${top.map((p,i)=>`<article class="podium-place place-${rank(p)}" data-podium-rank="${rank(p)}"><div class="podium-avatar">${p.avatar}</div><span class="podium-rank">${rank(p)===1?'★':rank(p)}</span><h2>${esc(p.name)}</h2><strong>${fmt(p.score)} <small>pts</small></strong></article>`).join('')}</div><section class="final-ranking"><h2>Tous les joueurs</h2>${list.map(p=>`<div class="final-player ${p.id===room.me?'is-me':''}"><b class="final-rank">${rank(p)}</b><span class="final-avatar">${p.avatar}</span><div><strong>${esc(p.name)}</strong><p>${f.statsAvailable===false?'Statistiques non enregistrées':`${p.stats?.exact||0} exacte${(p.stats?.exact||0)>1?'s':''} · série de ${p.stats?.bestStreak||0}`}</p></div><b class="final-score">${fmt(p.score)}<small>points</small></b></div>`).join('')}</section>${f.statsAvailable===false?'':trophies(list)}<details class="game-review"><summary>Revoir les ${f.history.length} produits enregistrés</summary><div>${f.history.map(h=>`<details><summary><span>${esc(modes[h.mode]?.name||'Nutri-Score')}</span><strong>${esc(h.name)}</strong><b>${esc(h.answer)}${h.skipped?' · passé':''}</b></summary>${h.insights?`<ul>${h.insights.points.map(p=>`<li><b>${esc(p.label)}</b> — ${esc(p.text)}</li>`).join('')}</ul><p>${esc(h.insights.note)}</p>`:''}</details>`).join('')}</div></details><div class="final-actions"><p id="final-status"></p><div id="final-buttons"></div><button class="secondary-button" data-action="leave">Quitter la table</button></div><p class="final-footnote">Prends ton temps. Aucun minuteur ici. Une nouvelle partie démarre seulement quand l’hôte la lance.</p></section>`;window.scrollTo({top:0,behavior:'instant'});initTrophies();revealPodium(f.gameId);}
let podiumTimers=[];
function revealPodium(gameId){podiumTimers.forEach(clearTimeout);podiumTimers=[];const board=$('.final-board'),cards=[...board.querySelectorAll('[data-podium-rank]')],ranks=[...new Set(cards.map(c=>Number(c.dataset.podiumRank)))].sort((a,b)=>b-a);let seen=false;try{seen=sessionStorage.getItem('podium:'+gameId)==='seen';sessionStorage.setItem('podium:'+gameId,'seen');}catch{}if(seen||matchMedia('(prefers-reduced-motion:reduce)').matches)return;board.classList.add('podium-revealing');cards.forEach(c=>c.classList.add('podium-wait'));ranks.forEach((rank,i)=>podiumTimers.push(setTimeout(()=>{if(!board.isConnected)return;cards.filter(c=>Number(c.dataset.podiumRank)===rank).forEach(c=>{c.classList.remove('podium-wait');c.classList.add('podium-arrive');});sfx(rank===1?'winner':'podium','podium:'+gameId+':'+rank);if(rank===1)window.NutriJuice.fireworks('winner:'+gameId);else window.NutriJuice.burst({key:'podium:'+gameId+':'+rank,count:65,firework:true});},450+i*1200)));podiumTimers.push(setTimeout(()=>{if(board.isConnected)board.classList.remove('podium-revealing');},ranks.length*1200+500));}
function updateFinalStatus(){const el=$('#final-status');if(!el)return;el.textContent=room.phase==='lobby'?'Le salon est ouvert pour préparer la suite. Ton palmarès reste ici.':'La partie est terminée. Tu peux consulter les résultats aussi longtemps que tu veux.';const buttons=$('#final-buttons'),key=String(isHost())+room.phase;if(buttons.dataset.key!==key){buttons.dataset.key=key;buttons.innerHTML=isHost()?'<button class="primary-button" data-action="prepare">Préparer une autre partie</button>':room.phase==='lobby'?'<button class="primary-button" data-action="show-lobby">Rejoindre le salon</button>':'<p class="subtle">La prochaine partie sera lancée par l’hôte.</p>';}}

function render(){topBar();if(!room){if(roomId){app.innerHTML='<div class="entry"><div class="loading-ring"></div><p>Connexion au salon…</p></div>';return;}if(viewKey!=='entry'){entry();viewKey='entry';}return;}
const wheelScene=room?.roulette&&['wheel','intro'].includes(room.phase);const final=room.me&&showFinal(),key=!room.me?'join:'+room.phase:final?'final:'+room.lastFinal?.gameId:wheelScene?'roulette:'+room.gameId+':'+room.round:room.phase==='lobby'||room.phase==='loading'?'lobby':room.phase==='intro'?'intro:'+room.gameId+':'+room.mode:'game:'+room.gameId+':'+room.round;
if(key!==viewKey){closeInspection();stopTrophies();clearResultShow();app.querySelectorAll('.nd-card').forEach(window.NutriDeckCards.dispose);viewKey=key;document.querySelector('.app-header').inert=room.phase==='intro';if(!room.me)entry();else if(final)finalScreen();else if(key==='lobby'){selected=mine().avatar;lobby();}else if(wheelScene)rouletteScreen();else if(room.phase==='intro')introScreen();else gameShell();}
if(!room.me){readyDock(false);return;}if(final){readyDock(false);updateFinalStatus();return;}if(['lobby','loading'].includes(room.phase)){readyDock(false);roster();const loading=room.phase==='loading';$('#lobby-actions').innerHTML=loading?'<div class="loading-ring"></div><p>Tirage des produits dans Open Food Facts…</p>':isHost()?`<button class="primary-button" data-action="start">Jouer · ${room.total} questions</button><p>${room.players.length===1?'Tu peux aussi jouer en solo.':''}</p>`:'<p>En attente du départ donné par l’hôte.</p>';$('#lobby-error').hidden=!room.error;$('#lobby-error').textContent=room.error||'';if($('#guest-settings'))$('#guest-settings').textContent=`${countries[room.country]} · ${room.questionCount||room.total} questions · vote ${room.seconds} s · pause ${room.readySeconds} s`;$('#profile-form').querySelectorAll('input,select,button').forEach(x=>x.disabled=loading);return;}
if(wheelScene){readyDock(false);tickRoulette();return;}if(room.phase==='intro'){readyDock(true);return;}stagePhase();roster();readyDock(room.phase==='results'||room.roulette&&['answer','ranking'].includes(phase()));tick();}
function sfx(name,key){window.NutriAudio.play(name,key);}
function tone(freq=440,drum=false){sfx(drum?'tick':'tap');}
function cue(name,suffix=name){const key=room.gameId+':'+room.round+':'+suffix;sfx(name,key);const j=window.NutriJuice;if(name==='answer'){j.bounce($('#wheel')||$('.result-grade'),key+':pop');j.burst({key,color:categoryTheme[room.mode].color,count:80,firework:true});}if(name==='points'){j.bounce($('#show-points'),key);if(mine()?.vote===room.revealTarget){j.fireworks(key+':fireworks');sfx('firework',key+':sound');}}if(name==='speed')j.bounce($('#speed-bonus'),key);if(name.startsWith('category_'))j.burst({key,color:categoryTheme[room.mode].color,count:70});if(name==='wheelStop')j.burst({key,count:65,firework:true});if(name.startsWith('sticker')){const el=document.querySelector(`[data-sticker="${suffix.split('-').at(-1)}"]`),r=el?.getBoundingClientRect();if(r)j.burst({key,x:r.left+30,y:r.top+20,color:name==='stickerGood'?'#7edf80':name==='stickerBad'?'#f9786a':'#ffd27b',count:16});}}

let lastHaptic=0,hapticRound='';
function updateVoteJuice(){const active=room?.me&&room.phase==='vote';let hud=$('#vote-hud');if(!active){hud?.remove();document.body.classList.remove('has-vote-hud');}else{if(!hud){hud=document.createElement('div');hud.id='vote-hud';hud.className='vote-hud';hud.innerHTML='<div class="hud-copy"><span class="hud-starter"></span><b class="hud-title">Vote</b></div><b class="hud-seconds"></b><span class="hud-count"></span><button class="hud-sound" aria-label="Activer ou couper le son">♪</button><button class="hud-table" aria-label="Ouvrir les contrôles de la table">☰</button><div class="hud-track"><i></i></div>';hud.querySelector('.hud-table').onclick=manageTable;hud.querySelector('.hud-sound').onclick=()=>{sound=window.NutriAudio.toggle();topBar();};document.body.append(hud);document.body.classList.add('has-vote-hud');}const left=room.deadline?Math.max(0,(room.deadline-now())/1000):null,u=NutriRules.urgency(left??room.seconds,room.seconds);hud.dataset.urgency=left===null?0:u.level;hud.classList.toggle('running',left!==null);hud.style.setProperty('--time-left',left===null?1:u.ratio);hud.style.setProperty('--shake',(u.level*.65)+'px');hud.querySelector('.hud-sound').setAttribute('aria-pressed',sound);hud.querySelector('.hud-sound').textContent=sound?'♪':'♩';hud.querySelector('.hud-seconds').textContent=left===null?'—':Math.ceil(left)+' s';hud.querySelector('.hud-count').textContent=room.players.filter(p=>p.voted).length+'/'+room.players.length;hud.querySelector('.hud-starter').textContent=room.voteStarter?.avatar||'◷';hud.querySelector('.hud-title').textContent=left===null?'Vote':u.level>=2?'Dernières secondes !':'À vous de choisir';const key=room.gameId+':'+room.round;if(hapticRound!==key){hapticRound=key;lastHaptic=now();}if(left!==null&&left>0&&!document.hidden&&now()-lastHaptic>=u.interval){lastHaptic=now();window.NutriJuice.vibrate(u.pulse);if(u.level>=2)sfx('heartbeat');}if(inspection){let timer=inspection.querySelector('.inspection-timer');if(!timer){timer=document.createElement('div');timer.className='inspection-timer';inspection.querySelector('header').after(timer);}timer.textContent=left===null?'Vote':Math.ceil(left)+' secondes';timer.style.setProperty('--time-left',left===null?1:u.ratio);timer.dataset.urgency=u.level;}}
 if(!room?.me||!room.voteStarter||!room.voteStartedAt||!['vote','reveal'].includes(room.phase))return;const key=room.gameId+':'+room.round+':started';if(!window.NutriJuice.once(key))return;let seen=false;try{seen=sessionStorage.getItem(key)==='seen';sessionStorage.setItem(key,'seen');}catch{}if(seen||document.hidden||now()-room.voteStartedAt>3500)return;const starter=room.voteStarter,notice=document.createElement('div');notice.className='vote-trigger-notice';notice.setAttribute('role','status');notice.innerHTML=`<span class="trigger-avatar">${esc(starter.avatar)}</span><strong>${esc(starter.name)}</strong><span>a déclenché le vote</span><b>${room.seconds} secondes !</b>`;document.body.append(notice);setTimeout(()=>notice.remove(),2500);sfx('epic',key);window.NutriAudio.announce(starter.name,key);window.NutriJuice.vibrate([45,60,80]);window.NutriJuice.burst({key:key+':burst',count:80,color:categoryTheme[room.mode].color});window.NutriJuice.bounce(hud,key+':hud');
}
function tick(){updateVoteJuice();if(!room?.me)return;if(room.roulette&&['wheel','intro'].includes(room.phase)){tickRoulette();return;}tickReady();if(!$('#stage'))return;const p=phase();if(p!==phaseKey){stagePhase();roster();if(room.roulette)readyDock(['answer','ranking'].includes(p));}if(p==='vote'){const remaining=room.deadline?Math.max(0,(room.deadline-now())/1000):null,clock=$('#vote-clock');clock.classList.toggle('started',remaining!==null);clock.classList.toggle('urgent',remaining!==null&&remaining<=5);clock.style.setProperty('--remaining',remaining===null?1:remaining/room.seconds);$('#clock-number').textContent=remaining===null?'':String(Math.ceil(remaining)).padStart(2,'0');$('#clock-label').textContent=remaining===null?'':'SECONDES RESTANTES';$('#vote-status').textContent=room.players.filter(x=>x.voted).length+' / '+room.players.length+' ont voté';$('#vote-hint').textContent=pendingChoice?'Enregistrement…':mine()?.vote?'Vote '+mine().vote+' enregistré · modifiable':'Choisis ta réponse.';document.querySelectorAll('[data-grade]').forEach(b=>{b.setAttribute('aria-pressed',(pendingChoice||mine()?.vote)===b.dataset.grade);b.classList.toggle('pending',pendingChoice===b.dataset.grade);b.disabled=remaining!==null&&remaining<=0;});const beat=Math.ceil(remaining);if(remaining!==null&&beat<=5&&beat!==lastBeat){lastBeat=beat;if(beat>0)cue('countdown','countdown-'+beat);}}
if(p==='spinning'){const cfg=currentMode(),plan=room.revealPlan||[],key=room.gameId+':'+room.round;if(wheelStepKey!==key){wheelStepKey=key;wheelStep=-1;}let step=0;for(let i=0;i<plan.length;i++)if(plan[i].at<=now()-room.lockAt)step=i;step=Math.max(wheelStep,step);const val=plan[step]?.value||cfg.values[0],el=$('#wheel-value');if(el&&step!==wheelStep){const previous=plan[wheelStep]?.value;el.classList.toggle('reverse-tick',previous!=null&&(cfg.values.indexOf(val)-cfg.values.indexOf(previous)+cfg.values.length)%cfg.values.length===cfg.values.length-1);wheelStep=step;el.textContent=val;el.style.setProperty('--wheel-color',cfg.colors[cfg.values.indexOf(val)]);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){el.classList.remove('tick');void el.offsetWidth;el.classList.add('tick');}document.querySelectorAll('[data-wheel-grade]').forEach(x=>x.classList.toggle('selected',x.dataset.wheelGrade===val));if(now()<room.landAt)sfx('shuffle');}if(room.roulette&&now()>=room.landAt){const wheel=$('#wheel');if(wheel&&!wheel.classList.contains('reel-hit')){wheel.classList.add('reel-hit');wheel.style.setProperty('--wheel-color',cfg.colors[cfg.values.indexOf(room.revealTarget)]);el.classList.remove('tick');el.textContent=room.revealTarget;cue('answer');}}}
if(['answer','ranking'].includes(p)){const cfg=currentMode(),grade=room.revealTarget;$('#wheel')?.style.setProperty('--wheel-color',cfg.colors[cfg.values.indexOf(grade)]);document.querySelectorAll('[data-wheel-grade]').forEach(x=>x.classList.toggle('selected',x.dataset.wheelGrade===grade));const elapsed=now()-room.landAt,progress=matchMedia('(prefers-reduced-motion: reduce)').matches?1:Math.max(0,Math.min(1,elapsed/1000));room.players.forEach(x=>{const el=document.querySelector(`[data-total="${x.id}"]`);if(el)el.textContent=fmt(x.base+x.award*(1-(1-progress)**3));});updateInsights();}}
async function poll(){clearTimeout(pollTimer);if(!roomId||pollBusy)return;pollBusy=true;try{accept(await api('/'+roomId));}catch(e){if(e.status===404){app.innerHTML='<div class="error-box"><h1>Salon introuvable</h1><p>Vérifie le lien reçu.</p><a href="multiplayer.html">Créer un salon</a></div>';roomId=null;}else online(false);}finally{pollBusy=false;if(roomId)pollTimer=setTimeout(poll,document.hidden?5000:room?.roulette&&['wheel','intro','reveal','standings'].includes(room.phase)?250:room?.phase==='vote'?450:1000);}}
async function command(action,data={}){if(busy)return;busy=true;try{accept(await api('/'+roomId+'/'+action,{...data,round:room?.round,gameId:room?.gameId,step:room?.step}));if(['ready','profile','settings'].includes(action))sfx(action==='ready'?'ready':'tap');return true;}catch(e){sfx('error');toast(e.message);await poll();return false;}finally{busy=false;}}
async function vote(choice){if(choice!==mine()?.vote)sfx('vote');const button=document.querySelector(`[data-grade="${choice}"]`);window.NutriJuice.bounce(button);const r=button?.getBoundingClientRect();if(r)window.NutriJuice.burst({x:r.left+r.width/2,y:r.top+r.height/2,count:20,color:categoryTheme[room.mode].color});pendingChoice=choice;tick();if(voteBusy)return;voteBusy=true;while(pendingChoice&&room?.phase==='vote'){const chosen=pendingChoice,round=room.round;try{accept(await api('/'+roomId+'/vote',{choice:chosen,round,gameId:room.gameId}));if(pendingChoice===chosen)pendingChoice=null;}catch(e){pendingChoice=null;toast(e.message);await poll();break;}}pendingChoice=null;voteBusy=false;tick();}
async function share(copyOnly){const url=location.origin+'/?room='+roomId;if(!copyOnly&&navigator.share){try{await navigator.share({title:'Rejoins ma table NutriDeck',text:'On devine le Nutri-Score ensemble ?',url});return;}catch(e){if(e.name==='AbortError')return;}}try{await navigator.clipboard.writeText(url);toast('Lien copié. Colle-le dans Messenger.');}catch{let field=$('#manual-link');if(!field){field=document.createElement('input');field.id='manual-link';field.className='manual-copy';field.readOnly=true;field.setAttribute('aria-label','Lien du salon à copier');app.prepend(field);}field.value=url;field.focus();field.select();toast('Copie ce lien pour inviter tes joueurs.');}}
app.addEventListener('click',e=>{const inspect=e.target.closest('[data-inspect]');if(inspect){inspectProduct(Number(inspect.dataset.inspect));return;}const avatar=e.target.closest('[data-avatar]');if(avatar){sfx('tap');selected=avatar.dataset.avatar;if($('#selected-avatar'))$('#selected-avatar').textContent=selected;document.querySelectorAll('[data-avatar]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.avatar===selected));return;}const grade=e.target.closest('[data-grade]');if(grade){vote(grade.dataset.grade);return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='copy'||action==='share'){share(action==='copy');return;}if(action==='sound'){sound=window.NutriAudio.toggle();$('#sound').textContent='Son '+(sound?'on':'off');$('#sound').setAttribute('aria-pressed',sound);tone();return;}if(action==='skip'){$('#confirm-skip').showModal();return;}if(action==='settings'){command('settings',readOptions()).then(ok=>{if(ok){viewKey='';render();toast('Réglages appliqués.');}});return;}if(action==='start'){const options=readOptions();(async()=>{if(await command('settings',options)){toast('Tirage des produits…');command('start').then(ok=>{if(ok){clearTimeout(toastTimer);$('#toast').hidden=true;}});}})();return;}if(action==='prepare'){lobbyView=true;if(room.phase==='finished')command('lobby');else{viewKey='';render();}return;}if(action==='show-lobby'){lobbyView=true;viewKey='';render();return;}if(action==='leave'){(async()=>{if(await command('leave')){localStorage.removeItem('nutrideck.multiplayer.lastRoom');location.href='/';}})();return;}command(action);});
app.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='recover-form'){const code=new FormData(e.target).get('code');if(await command('recover',{code})){toast('Ta place est récupérée.');poll();}return;}if(e.target.id==='join-link-form'){const value=new FormData(e.target).get('invite').trim();let id=value;try{id=new URL(value,location.origin).searchParams.get('room')||value;}catch{}if(!/^[a-f0-9]{32}$/.test(id)){toast('Colle le lien d’invitation complet.');return;}location.href='/?room='+id;return;}const name=$('#name').value.trim();if(!name)return;profile={name,avatar:selected};localStorage.setItem('nutrideck.multiplayer.profile',JSON.stringify(profile));if(e.target.id==='profile-form'){if(await command('profile',profile)){viewKey='';render();toast('Profil enregistré.');}return;}if(busy)return;busy=true;const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const d=roomId?await api('/'+roomId+'/join',profile):await api('',{...profile,...readOptions(),operation:createOperation});accept(d);poll();}catch(e){toast(e.message);button.disabled=false;}finally{busy=false;}});
$('#cancel-skip').onclick=()=>$('#confirm-skip').close();$('#accept-skip').onclick=()=>{$('#confirm-skip').close();command('skip');};
for(const event of ['pageshow','online'])window.addEventListener(event,()=>poll());document.addEventListener('visibilitychange',()=>{if(!document.hidden){poll();tick();}});
if(roomId&&!/^[a-f0-9]{32}$/.test(roomId)){roomId=null;history.replaceState(null,'','multiplayer.html');toast('Lien de salon invalide.');}
render();if(roomId)poll();setInterval(tick,70);
